export function shippingCostCents(items: {
    priceCents: number;
    quantity: number;
    weightGrams: number;
}[], freeOverCents: number) {
    const subtotal = items.reduce((s, i) => s + i.priceCents * i.quantity, 0);
    if (subtotal >= freeOverCents)
        return 0;
    const weight = items.reduce((s, i) => s + i.weightGrams * i.quantity, 0);
    if (weight === 0)
        return 0;
    return weight <= 500 ? 499 : weight <= 2000 ? 799 : 1299;
}
